/**
 * Mapbox 오프라인 지도 컴포넌트
 * - 오프라인 팩이 다운로드된 경우 사용
 * - react-native-maps와 동일한 props 인터페이스 제공
 */
export function OfflineMapView({ locations, selectedLocation, cityId }: OfflineMapViewProps) {
  const cameraRef = useRef<MapboxGL.Camera>(null);

  // 지도 중심 좌표
  const centerLocation = selectedLocation || locations[0];

  // 초기 카메라 설정 계산
  const initialCamera = useMemo(() => {
    if (!centerLocation) return undefined;

    if (locations.length === 1 || selectedLocation) {
      // 단일 장소 또는 선택된 장소
      const center = selectedLocation || locations[0];
      return {
        centerCoordinate: [center.longitude, center.latitude] as [number, number],
        zoomLevel: 14,
      };
    }

    // 여러 검색 결과 - bounds 계산
    const coordinates = locations.map((loc) => [loc.longitude, loc.latitude]);
    const lngs = coordinates.map((c) => c[0]);
    const lats = coordinates.map((c) => c[1]);

    return {
      bounds: {
        ne: [Math.max(...lngs), Math.max(...lats)] as [number, number],
        sw: [Math.min(...lngs), Math.min(...lats)] as [number, number],
        paddingTop: 50,
        paddingRight: 50,
        paddingBottom: 50,
        paddingLeft: 50,
      },
    };
  }, [locations, selectedLocation, centerLocation]);

  // 지도 카메라 자동 조정
  useEffect(() => {
    if (!cameraRef.current) return;

    if (selectedLocation) {
      // 선택된 장소로 포커스
      cameraRef.current.setCamera({
        centerCoordinate: [selectedLocation.longitude, selectedLocation.latitude],
        zoomLevel: 14,
        animationDuration: 0, // 애니메이션 짧게
      });
    } else if (locations.length > 0) {
      // 여러 검색 결과가 있으면 모두 보이도록
      const coordinates = locations.map((loc) => [loc.longitude, loc.latitude] as [number, number]);

      cameraRef.current.fitBounds(
        [Math.min(...coordinates.map((c) => c[0])), Math.min(...coordinates.map((c) => c[1]))],
        [Math.max(...coordinates.map((c) => c[0])), Math.max(...coordinates.map((c) => c[1]))],
        [50, 50, 50, 50], // edgePadding
        0, // 애니메이션 짧게
      );
    }
  }, [locations, selectedLocation]);

  if (!centerLocation) {
    return <View style={styles.map} />;
  }

  return (
    <View style={styles.map}>
      <MapboxGL.MapView style={styles.map} styleURL={MapboxGL.StyleURL.Street}>
        <MapboxGL.Camera ref={cameraRef} {...initialCamera} animationDuration={0} />

        <MapboxGL.UserLocation visible={true} showsUserHeadingIndicator={true} />

        {/* 선택된 장소 마커 */}
        {selectedLocation && (
          <MapboxGL.PointAnnotation
            id={`selected-${selectedLocation.latitude}-${selectedLocation.longitude}`}
            coordinate={[selectedLocation.longitude, selectedLocation.latitude]}
            title={selectedLocation.name}
            snippet={selectedLocation.address}
          >
            <View
              style={{
                width: 30,
                height: 30,
                borderRadius: 15,
                backgroundColor: '#228B22',
                borderWidth: 3,
                borderColor: '#ffffff',
              }}
            />
          </MapboxGL.PointAnnotation>
        )}

        {/* 검색 결과 마커들 (선택 전) */}
        {!selectedLocation &&
          locations.map((location, index) => (
            <MapboxGL.PointAnnotation
              key={`marker-${location.latitude}-${location.longitude}-${index}`}
              id={`marker-${location.latitude}-${location.longitude}-${index}`}
              coordinate={[location.longitude, location.latitude]}
              title={location.name}
              snippet={location.address}
            >
              <View
                style={{
                  width: 24,
                  height: 24,
                  borderRadius: 12,
                  backgroundColor: '#228B22',
                  borderWidth: 2,
                  borderColor: '#ffffff',
                }}
              />
            </MapboxGL.PointAnnotation>
          ))}
      </MapboxGL.MapView>
    </View>
  );
}
import { useState, useEffect } from 'react';

export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}

import React, { createContext, useContext, useEffect, useRef, useState, useCallback } from 'react';
import { networkStore, useNetworkStore, useRealNetworkStatus } from '@/shared/store/network';
import { authStore, useAuthStore } from '@/shared/store/auth';
import { syncData } from './engine';

export type SyncRunResult =
  | { status: 'completed'; message: string }
  | { status: 'failed'; message: string }
  | { status: 'blocked'; message: string };

interface SyncContextValue {
  isSyncing: boolean;
  lastSyncedAt: Date | null;
  triggerManualSync: () => Promise<SyncRunResult>;
}

const SyncContext = createContext<SyncContextValue | undefined>(undefined);

export function useSyncContext() {
  const context = useContext(SyncContext);
  if (!context) {
    throw new Error('useSyncContext must be used within SyncProvider');
  }
  return context;
}

interface SyncProviderProps {
  children: React.ReactNode;
  isDatabaseReady: boolean;
  enablePeriodicSync?: boolean;
  syncInterval?: number;
}

export function SyncProvider({
  children,
  isDatabaseReady,
  enablePeriodicSync = false,
  syncInterval = 5 * 60 * 1000,
}: SyncProviderProps) {
  const networkStatus = useRealNetworkStatus();
  const overrideStatus = useNetworkStore((state) => state.overrideStatus);
  const isAuthInitialized = useAuthStore((state) => state.isInitialized);
  const isAuthenticated = useAuthStore((state) => state.isAuthenticated);
  const canSync =
    isDatabaseReady && isAuthInitialized && isAuthenticated && networkStatus === 'online' && overrideStatus === null;

  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncedAt, setLastSyncedAt] = useState<Date | null>(null);
  const inFlightRef = useRef<Promise<SyncRunResult> | null>(null);
  const databaseReadyRef = useRef(isDatabaseReady);
  databaseReadyRef.current = isDatabaseReady;
  const previouslyEligibleRef = useRef(false);

  const executeSync = useCallback((): Promise<SyncRunResult> => {
    // 이전 render의 callback과 자동/수동 호출도 같은 진행 중 실행을 기다린다.
    if (inFlightRef.current) {
      return inFlightRef.current;
    }

    let blockedMessage: string | null = null;
    if (!databaseReadyRef.current) {
      blockedMessage = '데이터베이스가 준비되지 않아 동기화할 수 없습니다.';
    } else if (!authStore.isInitialized || !authStore.isAuthenticated) {
      blockedMessage = '로그인 준비가 완료된 뒤 동기화할 수 있습니다.';
    } else if (networkStore.override !== null) {
      blockedMessage = '네트워크 강제 설정 중에는 동기화할 수 없습니다. 실제 상태로 되돌려 주세요.';
    } else if (networkStore.realStatus !== 'online') {
      blockedMessage = '인터넷 연결이 확인된 뒤 동기화할 수 있습니다.';
    }
    if (blockedMessage) {
      return Promise.resolve({ status: 'blocked', message: blockedMessage });
    }

    let resolveRun!: (result: SyncRunResult) => void;
    const run = new Promise<SyncRunResult>((resolve) => {
      resolveRun = resolve;
    });
    // React 표시 상태를 갱신하기 전에 실행 소유권을 선점한다.
    inFlightRef.current = run;
    previouslyEligibleRef.current = true;
    setIsSyncing(true);

    (async () => {
      let result: SyncRunResult;
      try {
        await syncData();
        setLastSyncedAt(new Date());
        // engine가 반환됐음을 뜻한다. queue 전체 반영 여부는 engine의 결과 계약에 따른다.
        result = { status: 'completed', message: '동기화가 완료되었습니다.' };
      } catch {
        result = { status: 'failed', message: '동기화에 실패했습니다.' };
      }
      inFlightRef.current = null;
      setIsSyncing(false);
      resolveRun(result);
    })();

    return run;
  }, []);

  // 최초 준비 완료, 로그인, 연결 복구, 강제 설정 해제가 같은 시작 경계를 사용한다.
  useEffect(() => {
    const wasEligible = previouslyEligibleRef.current;
    previouslyEligibleRef.current = canSync;
    if (canSync && !wasEligible) {
      executeSync();
    }
  }, [canSync, executeSync]);

  useEffect(() => {
    if (!enablePeriodicSync) {
      return;
    }
    const intervalId = setInterval(() => {
      executeSync();
    }, syncInterval);
    return () => clearInterval(intervalId);
  }, [enablePeriodicSync, syncInterval, executeSync]);

  return (
    <SyncContext.Provider value={{ isSyncing, lastSyncedAt, triggerManualSync: executeSync }}>
      {children}
    </SyncContext.Provider>
  );
}
