    previouslyEligibleRef.current = canSync;
    if (canSync && !wasEligible) {
      executeSync();
    }
  }, [canSync, executeSync]);

  useEffect(() => {
    if (!enablePeriodicSync) {
      return;
    }
    const intervalId = setInterval(() => {
      executeSync();
    }, syncInterval);
    return () => clearInterval(intervalId);
  }, [enablePeriodicSync, syncInterval, executeSync]);

