 67	function createNetworkActions(
 68	  set: StoreApi<NetworkState>['setState'],
 69	  get: StoreApi<NetworkState>['getState'],
 70	): Pick<NetworkState, 'init' | 'cleanup' | 'refresh'> {
 71	  let currentSession: NetworkSession | null = null;
 72	
 73	  function init() {
 74	    if (currentSession) {
 75	      return;
 76	    }
 77	
 78	    const session: NetworkSession = {
 79	      unsubscribe: null,
 80	      noticeTimer: null,
 81	      observationVersion: 0,
 82	      refreshRequest: null,
 83	    };
 84	
 85	    currentSession = session;
 86	    beginUnknownCheck(session);
 87	    subscribe(session);
 88	  }
 89	
 90	  function cleanup() {
 91	    const session = currentSession;
 92	    currentSession = null;
 93	
 94	    if (session) {
 95	      clearNoticeTimer(session);
 96	      session.refreshRequest?.finish();
 97	      session.unsubscribe?.();
 98	    }
 99	
100	    set({ realStatus: 'unknown', checkStatus: 'checking', isRefreshing: false });
101	  }
102	
103	  function refresh(): Promise<void> {
104	    init();
105	
106	    const session = currentSession;
107	
108	    if (!session) {
109	      return Promise.resolve();
110	    }
111	
112	    if (session.refreshRequest) {
113	      return session.refreshRequest.promise;
114	    }
115	
116	    if (get().realStatus === 'unknown') {
117	      beginUnknownCheck(session);
118	    }
119	
120	    if (!subscribe(session)) {
121	      return Promise.resolve();
122	    }
123	
124	    const request = startRefreshRequest(session);
125	
126	    try {
127	      NetInfo.refresh().then(request.accept, request.fail);
128	    } catch {
129	      request.fail();
130	    }
131	
132	    return request.promise;
133	  }
134	
135	  function markUnavailable(session: NetworkSession) {
136	    if (currentSession !== session || get().realStatus !== 'unknown') {
137	      return;
138	    }
139	
140	    clearNoticeTimer(session);
141	
142	    if (get().checkStatus === 'unavailable') {
143	      return;
144	    }
145	
146	    set({ checkStatus: 'unavailable' });
147	  }
148	
149	  function beginUnknownCheck(session: NetworkSession) {
150	    clearNoticeTimer(session);
151	    session.noticeTimer = setTimeout(() => markUnavailable(session), CHECK_NOTICE_DELAY);
152	    set({ realStatus: 'unknown', checkStatus: 'checking' });
153	  }
154	
155	  function applyObservation(session: NetworkSession, state: NetInfoState) {
156	    if (currentSession !== session) {
157	      return;
158	    }
159	
160	    const status = resolveNetworkStatus(state);
161	
162	    if (status === get().realStatus) {
163	      return;
164	    }
165	
166	    if (status === 'unknown') {
167	      beginUnknownCheck(session);
168	    } else {
169	      clearNoticeTimer(session);
170	      set({ realStatus: status, checkStatus: 'idle' });
171	    }
172	  }
173	
174	  function subscribe(session: NetworkSession): boolean {
175	    if (session.unsubscribe) {
176	      return true;
177	    }
178	
179	    try {
180	      // 등록 자체가 첫 상태를 조회하므로 앱의 추가 fetch는 사용하지 않는다.
181	      session.unsubscribe = NetInfo.addEventListener((state) => {
182	        if (currentSession !== session) {
183	          return;
184	        }
185	
186	        session.observationVersion += 1;
187	        applyObservation(session, state);
188	      });
189	
190	      return true;
191	    } catch {
192	      markUnavailable(session);
193	      return false;
194	    }
195	  }
196	
197	  function startRefreshRequest(session: NetworkSession): NetworkRefreshRequest {
198	    const startingObservationVersion = session.observationVersion;
199	    let resolveRefresh!: () => void;
200	
201	    const promise = new Promise<void>((resolvePromise) => {
202	      resolveRefresh = resolvePromise;
203	    });
204	
205	    function canApplyResult() {
206	      return (
207	        currentSession === session &&
208	        session.refreshRequest === request &&
209	        session.observationVersion === startingObservationVersion
210	      );
211	    }
212	
213	    function finish() {
214	      clearTimeout(timeout);
215	
216	      if (session.refreshRequest === request) {
217	        session.refreshRequest = null;
218	
219	        if (currentSession === session) {
220	          set({ isRefreshing: false });
221	        }
222	      }
223	
224	      resolveRefresh();
225	    }
226	
227	    const request: NetworkRefreshRequest = {
228	      promise,
229	      accept: (state) => {
230	        if (canApplyResult()) {
231	          applyObservation(session, state);
232	        }
233	
234	        finish();
235	      },
236	      fail: () => {
237	        if (canApplyResult()) {
238	          markUnavailable(session);
239	        }
240	
241	        finish();
242	      },
243	      finish,
244	    };
245	
246	    session.refreshRequest = request;
247	    // 미응답 요청의 앱 대기만 해제한다. 늦은 실측은 기존 listener로 받는다.
248	    const timeout = setTimeout(request.fail, REFRESH_WAIT_LIMIT);
249	    set({ isRefreshing: true });
250	
251	    return request;
252	  }
253	
254	  return { init, cleanup, refresh };
255	}
