  2	import { networkStore, useRealNetworkStatus, type NetworkStatus } from '@/shared/store/network';
  3	import { syncData } from './engine';
  4	
  5	/**
  6	 * SyncProvider Context
  7	 *
  8	 * 동기화 상태와 수동 트리거 제공
  9	 */
 10	interface SyncContextValue {
 11	  isSyncing: boolean;
 12	  lastSyncedAt: Date | null;
 13	  triggerManualSync: () => Promise<void>;
 14	}
 15	
 16	const SyncContext = createContext<SyncContextValue | undefined>(undefined);
 17	
 18	/**
 19	 * useSyncContext Hook
 20	 *
 21	 * 컴포넌트에서 동기화 상태와 수동 트리거 접근
 22	 *
 23	 * @example
 24	 * ```tsx
 25	 * const { isSyncing, triggerManualSync } = useSyncContext();
 26	 * ```
 27	 */
 28	export function useSyncContext() {
 29	  const context = useContext(SyncContext);
 30	  if (!context) {
 31	    throw new Error('useSyncContext must be used within SyncProvider');
 32	  }
 33	  return context;
 34	}
