 36	/**
 37	 * 동기화 Provider
 38	 *
 39	 * 앱 전체를 감싸서 자동 동기화 기능 제공 (Push + Pull)
 40	 * - 네트워크 상태 감지
 41	 * - 오프라인 → 온라인 전환 시 자동 동기화
 42	 * - 앱 시작 시 한 번 동기화
 43	 * - 주기적 동기화 (선택적)
 44	 * - 디버그 모드: 강제 온라인/오프라인 설정 가능
 45	 *
 46	 * @example
 47	 * ```tsx
 48	 * <SyncProvider enablePeriodicSync={false}>
 49	 *   <App />
 50	 * </SyncProvider>
 51	 * ```
 52	 */
 53	interface SyncProviderProps {
 54	  children: React.ReactNode;
 55	  enablePeriodicSync?: boolean; // 주기적 동기화 활성화 (기본: false)
 56	  syncInterval?: number; // 주기적 동기화 간격 (ms, 기본: 5분)
 57	}
 58	
 59	export function SyncProvider({
 60	  children,
 61	  enablePeriodicSync = false,
 62	  syncInterval = 5 * 60 * 1000, // 5분
 63	}: SyncProviderProps) {
 64	  const networkStatus = useRealNetworkStatus();
 65	
 66	  const [isSyncing, setIsSyncing] = useState(false);
 67	  const [lastSyncedAt, setLastSyncedAt] = useState<Date | null>(null);
 68	  // null은 첫 effect 미처리이며, 실제 네트워크의 unknown과 구분한다.
 69	  const previousStatusRef = useRef<NetworkStatus | null>(null);
 70	
 71	  /**
 72	   * 동기화 실행 함수 (중복 실행 방지)
 73	   */
 74	  const executeSync = useCallback(
 75	    async (reason: string) => {
 76	      if (networkStore.realStatus !== 'online' || networkStore.override !== null) {
 77	        return;
 78	      }
 79	
 80	      if (isSyncing) {
 81	        console.log('⏭️ [SyncProvider] Sync already in progress, skipping...');
 82	        return;
 83	      }
 84	
 85	      try {
 86	        setIsSyncing(true);
 87	        console.log(`🔄 [SyncProvider] Sync triggered: ${reason}`);
 88	
 89	        await syncData(); // Push + Pull
 90	
 91	        const now = new Date();
 92	        setLastSyncedAt(now);
 93	
 94	        console.log(`✅ [SyncProvider] Sync completed: ${reason}`, {
 95	          lastSyncedAt: now.toISOString(),
 96	        });
 97	      } catch (error) {
 98	        console.error(`❌ [SyncProvider] Sync failed: ${reason}`, error);
 99	      } finally {
100	        setIsSyncing(false);
101	      }
102	    },
103	    [isSyncing],
104	  );
105	
106	  /**
107	   * 수동 동기화 트리거 (UI에서 호출)
108	   */
109	  const triggerManualSync = useCallback(async () => {
110	    await executeSync('Manual trigger');
111	  }, [executeSync]);
112	
113	  /**
114	   * 최초 online과 이후 online 전환마다 한 번 동기화
115	   */
116	  useEffect(() => {
117	    const previousStatus = previousStatusRef.current;
118	    previousStatusRef.current = networkStatus;
119	
120	    // 최초 unknown 확정과 오프라인 복구 모두 실제 online에서 시작한다.
121	    if (previousStatus !== 'online' && networkStatus === 'online') {
122	      if (previousStatus === null) {
123	        console.log('🚀 [SyncProvider] Initial sync on app start');
124	        executeSync('App startup');
125	      } else {
126	        console.log('🌐 [SyncProvider] Network recovered → Starting sync');
127	        executeSync('Network recovery');
128	      }
129	    }
130	
131	    // 온라인 → 오프라인 전환 로그
132	    if (previousStatus === 'online' && networkStatus === 'offline') {
133	      console.log('📴 [SyncProvider] Network offline → Sync paused');
134	    }
135	  }, [networkStatus, executeSync]);
136	
137	  /**
138	   * 주기적 동기화 (선택적)
139	   */
140	  useEffect(() => {
141	    if (!enablePeriodicSync) {
142	      return;
143	    }
144	
145	    console.log(`⏰ [SyncProvider] Periodic sync enabled (${syncInterval / 1000}s interval)`);
146	
147	    const intervalId = setInterval(() => {
148	      if (networkStatus === 'online') {
149	        executeSync('Periodic sync');
150	      } else {
151	        console.log('⏭️ [SyncProvider] Skipping periodic sync (offline)');
152	      }
153	    }, syncInterval);
154	
155	    return () => clearInterval(intervalId);
156	  }, [enablePeriodicSync, syncInterval, networkStatus, executeSync]);
157	
158	  /**
159	   * Context Value
160	   */
161	  const value: SyncContextValue = {
162	    isSyncing,
163	    lastSyncedAt,
164	    triggerManualSync,
165	  };
166	
167	  return <SyncContext.Provider value={value}>{children}</SyncContext.Provider>;
168	}
