 23	      local: () => TripLocal.getTripsLocal(),
 24	      remote: async () => {
 25	        const response = await TripApi.fetchAllTrips();
 26	        return response.data;
 27	      },
 28	    });
 29	  },
 30	
 31	  /**
 32	   * 특정 여행 조회
 33	   */
 34	  getById: async (id: string): Promise<Trip | undefined> => {
 35	    return await routeTripQuery({
 36	      local: () => TripLocal.getTripByIdLocal(id),
 37	      remote: async () => {
 38	        // TODO: fetchTripById API 필요시 추가
 39	        const response = await TripApi.fetchAllTrips();
 40	        return response.data.find((trip) => trip.id === id);
 41	      },
 42	    });
 43	  },
 44	
 45	  /**
 46	   * 여행 생성
 47	   */
 48	  create: async (data: CreateTripRequest): Promise<Trip> => {
 49	    return await routeTripMutation({
 50	      local: () => TripLocal.createTripLocal(data),
 51	      remote: () => TripApi.fetchCreateTrip(data),
 52	    });
 53	  },
 54	
 55	  /**
 56	   * 여행 수정
 57	   */
 58	  update: async (id: string, data: UpdateTripRequest): Promise<Trip> => {
 59	    return await routeTripMutation({
 60	      local: () => TripLocal.updateTripLocal(id, data),
 61	      remote: () => TripApi.fetchUpdateTrip(id, data),
 62	    });
 63	  },
 64	
 65	  /**
 66	   * 여행 삭제 (Soft Delete)
 67	   */
 68	  delete: async (id: string): Promise<DeleteTripResponse> => {
 69	    return await routeTripMutation({
 70	      local: () => TripLocal.deleteTripLocal(id),
 71	      remote: () => TripApi.fetchDeleteTrip(id),
 72	    });
 73	  },
 74	};
