    await act(async () => {
      await expect(
        result.current.mutateAsync({ id: 'schedule-b', tripId: 'trip-b', data: { title: '작성 중 입력' } }),
      ).rejects.toBe(blocked);
    });

    expect(ScheduleRepository.update).toHaveBeenCalledWith('schedule-b', 'trip-b', { title: '작성 중 입력' });
