      ).rejects.toBe(blocked);
    });

    expect(ExpenseRepository.update).toHaveBeenCalledWith('expense-b', 'trip-b', { title: '작성 중 입력' });
  });

  it('경비 삭제의 제한 오류도 caller에게 그대로 전달한다', async () => {
