});

it.each([{ isLoading: true, isError: false, status: 'loading' }, { isLoading: false, isError: true, status: 'error' }, { isLoading: false, isError: false, status: 'ready' }])('일반 로딩/오류/성공한 빈 결과를 구별한다: $status', ({ isLoading, isError, status }) => {
  const { result } = renderHook(() => useTripContentAccess('b', { isLoading, isError, refetch: jest.fn(async () => success) }));
