  tripId: z.string().ulid(),
  scheduleId: z.string().ulid().nullable(),
  title: z.string(),
  amount: z.string(), // DB decimal → string
  currency: z.string(),
  category: z.string(),
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, {
    message: 'Date must be in YYYY-MM-DD format',
  }), // ISO date string (e.g., "2024-03-15")
